// @ts-check

/**
 * `docs/MCP_REFERENCE.md` is generated by `scripts/gen-mcp-reference.js`.
 * This reruns the generator in memory and fails when the checked-in page
 * differs, naming the command that regenerates it. The structural checks
 * below hold the page to one entry per tool and prompt, each with the rows
 * LLP 0494#docs-reference lists, so a generator change cannot quietly drop
 * one.
 *
 * @ref LLP 0494#docs-reference [tests]: the drift test stands in for a docs-build hook; the page cannot differ from the registered verbs, contracts and prompts
 */

import test from 'node:test'
import assert from 'node:assert/strict'
import fs from 'node:fs/promises'

import { REFERENCE_PATH, REGENERATE, renderMcpReference } from '../../scripts/gen-mcp-reference.js'
import { REMOTE_TOOL_CONTRACTS } from '../../src/core/mcp/contracts.js'
import { listPrompts } from '../../src/core/mcp/prompts.js'

const page = await renderMcpReference()

/**
 * The text of one `### \`name\`` entry, up to the next heading.
 *
 * @param {string} name
 */
function entry(name) {
  const start = page.indexOf(`### \`${name}\`\n`)
  assert.ok(start >= 0, `no entry for ${name}`)
  const rest = page.slice(start + 1)
  const end = rest.search(/\n##/)
  return end < 0 ? rest : rest.slice(0, end)
}

test('the checked-in MCP reference matches the generator', async () => {
  const current = await fs.readFile(REFERENCE_PATH, 'utf8')
  assert.ok(current === page, `docs/MCP_REFERENCE.md is stale: run ${REGENERATE}`)
})

test('every tool has one entry with title, auth class, hints, exposure, CLI equivalent and schema', () => {
  const tools = [...page.matchAll(/^## (Local|Recommendation) tools$[\s\S]*?(?=^## )/gm)]
    .flatMap((section) => [...section[0].matchAll(/^### `([^`]+)`$/gm)].map((m) => m[1]))
  assert.equal(new Set(tools).size, tools.length, 'a tool has two entries')
  for (const contract of REMOTE_TOOL_CONTRACTS) assert.ok(tools.includes(contract.tool), `${contract.tool} is missing`)
  assert.ok(tools.includes('query_sql'), 'the core query_sql verb is missing')
  for (const name of tools) {
    const text = entry(name)
    for (const row of ['Title', 'Auth class', 'Hints', 'Exposure', 'CLI equivalent', 'Registered by']) {
      assert.match(text, new RegExp(`^\\| ${row} \\| \\S`, 'm'), `${name}: no ${row} row`)
    }
    assert.match(text, /^\| Argument \| Type \| Required \| Default \|/m, `${name}: no schema table`)
  }
})

test('each recommendation entry reads its contract', () => {
  for (const contract of REMOTE_TOOL_CONTRACTS) {
    const text = entry(contract.tool)
    assert.ok(text.includes(`| Title | ${contract.title} |`), `${contract.tool}: title`)
    assert.ok(text.includes(`| CLI equivalent | \`${contract.cli}\` |`), `${contract.tool}: CLI equivalent`)
    for (const arg of Object.keys(contract.inputSchema.properties)) {
      assert.ok(text.includes(`| \`${arg}\` |`), `${contract.tool}: argument ${arg}`)
    }
  }
})

test('the write contract shows its scope and non-read hints', () => {
  const write = REMOTE_TOOL_CONTRACTS.filter((c) => c.authClass === 'write')
  assert.ok(write.length > 0, 'no write contract')
  for (const contract of write) {
    const text = entry(contract.tool)
    assert.ok(text.includes(`| Auth class | \`write\`, scope \`${contract.scope}\`:`), `${contract.tool}: scope`)
    assert.ok(text.includes('| Hints | `readOnlyHint: false`, `destructiveHint: false` |'), `${contract.tool}: hints`)
  }
  assert.ok(entry('set_recommendation_status').includes('scope `report-publish`'))
})

test('every prompt has one entry with its transports, CLI equivalent and arguments', () => {
  const offered = new Set([
    ...listPrompts(new Set(), 'stdio'),
    ...listPrompts(new Set(REMOTE_TOOL_CONTRACTS.map((c) => c.tool)), 'http'),
  ].map((p) => p.name))
  const section = page.slice(page.indexOf('\n## Prompts\n'))
  const names = [...section.matchAll(/^### `([^`]+)`$/gm)].map((m) => m[1])
  assert.deepEqual(names.slice().sort(), [...offered].sort())
  for (const name of names) {
    const text = entry(name)
    for (const row of ['Title', 'Over stdio', 'Over `/v1/mcp`', 'CLI equivalent']) {
      assert.ok(text.includes(`| ${row} | `), `${name}: no ${row} row`)
    }
  }
})

test('server-only tools sit under one hand-written heading pointing to tools/list', () => {
  const at = page.indexOf('\n## Server-only tools\n')
  assert.ok(at >= 0)
  const text = page.slice(at, page.indexOf('\n## Prompts\n'))
  assert.ok(text.includes('`session_evidence`'))
  assert.ok(text.includes('`tools/list`'))
  assert.doesNotMatch(text, /^### /m)
})
